// ---------------------------------------------------------------------------
// config - the only node you edit.
//
// Nothing in this workflow reads $env, so it behaves identically on self-hosted
// n8n and on n8n Cloud, needs no N8N_BLOCK_ENV_ACCESS_IN_NODE, and a threshold
// change costs a save rather than a host restart.
//
// Leave a key blank and that step is SKIPPED, not failed:
//   LLM_API_KEY        blank -> the plain confirmation fallback is used
//   GHL_API_TOKEN      blank -> confirmations and reminders are not sent
//   LEADS_SHEET_ID     blank -> nothing is written to Sheets
//   ALERT_WEBHOOK_URL  blank -> no booking / calls-desk notifications
//
// LEADS_SHEET_ID is the only required value - fill in your Google Sheet ID.
// ---------------------------------------------------------------------------

const LLM_BASE_URL = 'https://llm.acme.example';
const LLM_API_KEY = '';
const LLM_MODEL = 'modelark/seed-2-0-pro-260328';
const LLM_MODEL_WRITER = 'modelark/seed-2-0-pro-260328';
const SENDER_INTRO = 'automation for SME operations';

const GHL_API_TOKEN = '';

const LEADS_SHEET_ID = 'YOUR_GOOGLE_SHEET_ID';

// Hours after the start time before an unmarked booking counts as a no-show.
const NOSHOW_GRACE_HOURS = 4;

// Where booking events and the daily calls desk get posted.
const ALERT_WEBHOOK_URL = '';

// ---------------------------------------------------------------------------
// derived - nothing below here needs editing
// ---------------------------------------------------------------------------

const llmApiKey = String(LLM_API_KEY || '').trim();
const ghlApiToken = String(GHL_API_TOKEN || '').trim();
const leadsSheetId = String(LEADS_SHEET_ID || '').trim();
const alertWebhookUrl = String(ALERT_WEBHOOK_URL || '').trim();
const llmModelWriter = String(LLM_MODEL_WRITER || '').trim() || String(LLM_MODEL || '').trim();

return [{
  json: {
    llm_base_url: String(LLM_BASE_URL || '').trim().replace(/\/+$/, ''),
    llm_api_key: llmApiKey,
    llm_model: String(LLM_MODEL || '').trim(),
    llm_model_writer: llmModelWriter,
    sender_intro: String(SENDER_INTRO || 'automation for SME operations').trim(),

    ghl_api_token: ghlApiToken,
    leads_sheet_id: leadsSheetId,
    noshow_grace_hours: Number(NOSHOW_GRACE_HOURS) || 4,
    alert_webhook_url: alertWebhookUrl,

    llm_enabled: llmApiKey !== '',
    ghl_enabled: ghlApiToken !== '',
    sheets_enabled: leadsSheetId !== '' && leadsSheetId !== 'YOUR_GOOGLE_SHEET_ID',
    notify_enabled: alertWebhookUrl !== ''
  }
}];

// Cal.com, Calendly and GHL all describe a booking differently. One shape from here on.
return $input.all().map((item) => {
  const b = item.json.body || item.json;
  const payload = b.payload || b;
  const attendee = (payload.attendees && payload.attendees[0]) || {};

  const email = String(
    attendee.email || payload.email || payload.contact_email || b.email || ''
  ).toLowerCase().trim();

  const startsAt = payload.startTime || payload.start_time || payload.startsAt || payload.appointmentStartTime || '';
  const triggerEvent = String(b.triggerEvent || b.type || b.event || '').toLowerCase();

  const cancelled = triggerEvent.indexOf('cancel') !== -1 || triggerEvent.indexOf('delete') !== -1;
  const rescheduled = triggerEvent.indexOf('reschedul') !== -1;

  return { json: {
    booking_id: payload.uid || payload.id || b.id || (email + '-' + startsAt),
    lead_id: (payload.metadata && payload.metadata.lead_id) || b.lead_id || email,
    email: email,
    name: attendee.name || payload.name || '',
    company: (payload.metadata && payload.metadata.company) || b.company || '',
    starts_at: startsAt,
    timezone: attendee.timeZone || payload.timezone || 'Asia/Singapore',
    event_type: cancelled ? 'cancelled' : (rescheduled ? 'rescheduled' : 'created'),
    ghl_contact_id: (payload.metadata && payload.metadata.ghl_contact_id) || '',
    received_at: new Date().toISOString()
  }};
});

// Fall back to a plain confirmation if the model call failed. A booking must always
// get a confirmation - that message is most of the reason people show up.
const bookings = $('still on the calendar?').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const booking = Object.assign({}, bookings[i].json);
  const res = $input.all()[i].json || {};
  const written = String(((((res.choices || [])[0]) || {}).message || {}).content || '').trim();

  booking.confirmation = written
    ? written
    : 'Confirmed for ' + booking.starts_at + '. I will come with one question about how your team handles this today.';

  booking.stage = 'booked';
  booking.reminder_sent = 'no';
  booking.outcome = '';
  out.push({ json: booking });
}

return out;

// A cancellation is not a loss. Put them back in the pipeline with a re-book task
// rather than letting the row die at 'cancelled'.
return $input.all().map((item) => ({ json: Object.assign({}, item.json, {
  stage: 'replied',
  outcome: 'cancelled',
  rebook_due: new Date(Date.now() + 3 * 86400000).toISOString().slice(0, 10),
  reminder_sent: 'n/a'
})}));

// Two jobs: remind tomorrow's calls, and close out yesterday's that nobody marked.
// An unmarked past booking is treated as a no-show after a grace period, because the
// alternative - assuming it went fine - is how pipelines fill up with ghosts.
const GRACE_HOURS = Number($('config').first().json.noshow_grace_hours || 4);
const now = Date.now();
const out = [];

for (const item of $input.all()) {
  const b = item.json;
  const starts = Date.parse(b.starts_at || '') || 0;
  if (!starts) continue;
  if (String(b.outcome || '')) continue;

  const hoursAway = (starts - now) / 3600000;

  if (hoursAway > 0 && hoursAway <= 24 && String(b.reminder_sent || 'no') === 'no') {
    out.push({ json: Object.assign({}, b, { action: 'remind' }) });
    continue;
  }

  if (hoursAway < -GRACE_HOURS) {
    out.push({ json: Object.assign({}, b, { action: 'noshow' }) });
  }
}

if (out.length === 0) return [{ json: { action: 'none' } }];
return out;

// Mark reminded so tomorrow's run does not send it twice.
const source = $('reminder due?').all();
return source.map((item) => ({ json: {
  booking_id: item.json.booking_id,
  reminder_sent: 'yes',
  reminder_sent_at: new Date().toISOString()
}}));

// No-shows. Set the outcome and a re-book date; the sales person gets a nudge, and
// the lead is not silently abandoned. 'none' items pass through untouched.
return $input.all()
  .filter((item) => item.json.action === 'noshow')
  .map((item) => ({ json: {
    booking_id: item.json.booking_id,
    lead_id: item.json.lead_id,
    outcome: 'no_show',
    rebook_due: new Date(Date.now() + 2 * 86400000).toISOString().slice(0, 10),
    closed_at: new Date().toISOString()
  }}));

// Morning line for the sales person. Silent when there is nothing on.
let reminded = [];
let noshows = [];
try { reminded = $('mark reminded').all(); } catch (e) { reminded = []; }
try { noshows = $('mark no-shows').all(); } catch (e) { noshows = []; }

if (!reminded.length && !noshows.length) return [];

const lines = [':calendar: *Calls desk*'];
if (reminded.length) lines.push(reminded.length + ' reminder' + (reminded.length === 1 ? '' : 's') + ' sent for today and tomorrow.');
if (noshows.length) lines.push(':ghost: *' + noshows.length + ' no-show' + (noshows.length === 1 ? '' : 's') + ' closed out.* Re-book task due in two days - they are in the Bookings tab with `outcome: no_show`.');

return [{ json: { text: lines.join('\n') } }];
